window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a0c36af2b06e209b"]={"versions": [{"id": "FIG-a0c36af2b06e209b", "releases": ["R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (<em>Interaction Diagram</em>) mit Interaktionsrahmen (<em>Combined Fragment</em> <code>loop</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (ab R21-11, fortgeführt in R22-11/R23-11), Spezifikation <code>AUTOSAR_CP_SWS_MemoryAccess</code>.</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des asynchronen Verarbeitungsmodells für segmentierte Löschoperationen (<em>Erase Job Processing</em>) über die Abstraktionsschicht des Memory Access Modules (<code>MemAcc</code>) hinunter zum Hardware-Treiber (<code>Mem</code>). Es visualisiert die Entkopplung von synchroner Job-Annahme, zyklischer Sektor-Abarbeitung via Scheduler (<code>SchM</code>) und abschließender asynchroner Rückmeldung per Callback (<code>JobEndNotification</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & BSW-Module (Lifelines):</strong></li>\n<li><code>Upper Layer</code> (Akteur/BSW-Modul): Typischerweise <code>NvM</code> (NVRAM Manager), Flash-Bootloader, Update-Manager oder Diagnose-Dienste (UDS).</li>\n<li><code>«module» :SchM</code> (BSW-Scheduler / RTE): Triggert zyklische Tasks (<code>MainFunctions</code>) der Basic Software.</li>\n<li><code>«module» :MemAcc</code> (Memory Access): Standardisiertes Abstraktionsmodul für segmentierten Speicherzugriff (Nachfolger/Ergänzung zu <code>MemIf</code>/<code>Fee</code>/<code>Fls</code>). Verwaltet logische Adressräume, Job-Queuing, Zerlegung in physische Sektorgrenzen und Priorisierung.</li>\n<li><code>«module» :Mem</code> (Memory Driver): MCAL- oder hardwarenaher Speichertreiber (gemäß <code>AUTOSAR_SWS_MemoryDriver</code>, abstrahierter Treiber für On-Chip/Off-Chip Flash, EEPROM oder Multi-Partition Flash).</li>\n<li><strong>Interaktionsrahmen:</strong></li>\n<li><code>loop Sector</code>: Wiederholungsschleife für jeden physischen Sektor des angeforderten Löschbereichs.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Synchrone Job-Initiierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Upper Layer</code> ruft <code>MemAcc_Erase(JobId, Address, Length)</code> auf.</li>\n<li><code>MemAcc</code> validiert Parameter, prüft Modulstatus/Hardware-Verfügbarkeit, puffert den Auftrag in der internen Job-Queue und kehrt synchron mit Rückgabewert (<code>E_OK</code> bzw. Fehlercode) zu <code>Upper Layer</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Verarbeitung & Sektor-Zerlegung (<code>loop Sector</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>SchM</code> aktiviert periodisch <code>MemAcc_MainFunction()</code>.</li>\n<li>Pro Schleifendurchlauf initiiert <code>MemAcc</code> das Löschen des aktuellen physischen Sektors via <code>Mem_Erase(InstanceId, TargetAddress, Length)</code>. <code>Mem</code> nimmt den Low-Level-Job an und quittiert synchron.</li>\n<li><code>MemAcc_MainFunction()</code> ruft die Treiber-Zustandsmaschine <code>Mem_MainFunction()</code> auf (bzw. diese läuft parallel via SchM), um den hardwareseitigen Löschvorgang (z. B. Flash Controller Status-Register-Abfrage) voranzutreiben.</li>\n<li><code>MemAcc</code> pollt das Ergebnis des Sektor-Jobs synchron über <code>Mem_GetJobResult(InstanceId)</code>. Sobald das Ergebnis <code>MEM_JOB_OK</code> signalisiert, inkrementiert <code>MemAcc</code> auf die nächste Sektoradresse, bis alle Sektoren der ursprünglichen Gesamtlänge gelöscht sind.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Benachrichtigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Abschluss aller Sektoren triggert <code>MemAcc</code> aus dem Kontext der <code>MemAcc_MainFunction</code> den konfigurierten Callback <code>&lt;UpperLayer&gt;_JobEndNotification()</code>.</li>\n<li><code>Upper Layer</code> übernimmt die Weiterverarbeitung (z. B. Schreibfreigabe oder Statusübergabe an <code>NvM</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (Nicht-blockierend):</strong> <code>MemAcc_Erase()</code> ist strikt asynchron auszulegen. Es darf keine Busy-Wait-Schleifen auf Hardware-Ebene enthalten.</li>\n<li><strong>Sektor-Alignment & Granularität:</strong> <code>MemAcc</code> übernimmt das Mapping von logischen Bereichen auf physische Sektorgrenzen (<code>Sector Erase Sizes</code>). Anwendungsentwickler müssen sicherstellen, dass Längen- und Adressangaben den im BSW-Konfigurator hinterlegten Sektor-Restriktionen (<code>MemAccSectorBatch</code>, <code>MemAccAddressArea</code>) genügen.</li>\n<li><strong>Task-Scheduling (SchM):</strong></li>\n<li>Die Taktrate von <code>MemAcc_MainFunction()</code> und <code>Mem_MainFunction()</code> bestimmt maßgeblich die Latenz zwischen den Einzelsektor-Löschvorgängen.</li>\n<li>Werden beide Funktionen in derselben Task oder in unterschiedlichen BSW-Tasks ausgeführt, muss auf Reentrancy-Regeln und Mutex-Konfigurationen (<code>SchM_Enter_MemAcc</code>, <code>SchM_Exit_MemAcc</code>) geachtet werden.</li>\n<li><strong>Callback-Restriktionen (<code>JobEndNotification</code>):</strong> Der Callback wird im Kontext der <code>MemAcc_MainFunction()</code> ausgeführt (BSW-Task-Kontext). Dort dürfen keine langwierigen oder blockierenden Operationen ausgeführt werden, um Deadlocks oder Task-Jitter im BSW-Scheduler zu verhindern.</li>\n</ul>"}, {"id": "FIG-3e845dd7133023bc", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (<em>Interaction Diagram</em>) mit Interaktionsrahmen (<em>Combined Fragment</em> <code>loop</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (ab R21-11, fortgeführt in R22-11/R23-11), Spezifikation <code>AUTOSAR_CP_SWS_MemoryAccess</code>.</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des asynchronen Verarbeitungsmodells für segmentierte Löschoperationen (<em>Erase Job Processing</em>) über die Abstraktionsschicht des Memory Access Modules (<code>MemAcc</code>) hinunter zum Hardware-Treiber (<code>Mem</code>). Es visualisiert die Entkopplung von synchroner Job-Annahme, zyklischer Sektor-Abarbeitung via Scheduler (<code>SchM</code>) und abschließender asynchroner Rückmeldung per Callback (<code>JobEndNotification</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure & BSW-Module (Lifelines):</strong></li>\n<li><code>Upper Layer</code> (Akteur/BSW-Modul): Typischerweise <code>NvM</code> (NVRAM Manager), Flash-Bootloader, Update-Manager oder Diagnose-Dienste (UDS).</li>\n<li><code>«module» :SchM</code> (BSW-Scheduler / RTE): Triggert zyklische Tasks (<code>MainFunctions</code>) der Basic Software.</li>\n<li><code>«module» :MemAcc</code> (Memory Access): Standardisiertes Abstraktionsmodul für segmentierten Speicherzugriff (Nachfolger/Ergänzung zu <code>MemIf</code>/<code>Fee</code>/<code>Fls</code>). Verwaltet logische Adressräume, Job-Queuing, Zerlegung in physische Sektorgrenzen und Priorisierung.</li>\n<li><code>«module» :Mem</code> (Memory Driver): MCAL- oder hardwarenaher Speichertreiber (gemäß <code>AUTOSAR_SWS_MemoryDriver</code>, abstrahierter Treiber für On-Chip/Off-Chip Flash, EEPROM oder Multi-Partition Flash).</li>\n<li><strong>Interaktionsrahmen:</strong></li>\n<li><code>loop Sector</code>: Wiederholungsschleife für jeden physischen Sektor des angeforderten Löschbereichs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Synchrone Job-Initiierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Upper Layer</code> ruft <code>MemAcc_Erase(JobId, Address, Length)</code> auf.</li>\n<li><code>MemAcc</code> validiert Parameter, prüft Modulstatus/Hardware-Verfügbarkeit, puffert den Auftrag in der internen Job-Queue und kehrt synchron mit Rückgabewert (<code>E_OK</code> bzw. Fehlercode) zu <code>Upper Layer</code> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklische Verarbeitung & Sektor-Zerlegung (<code>loop Sector</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>SchM</code> aktiviert periodisch <code>MemAcc_MainFunction()</code>.</li>\n<li>Pro Schleifendurchlauf initiiert <code>MemAcc</code> das Löschen des aktuellen physischen Sektors via <code>Mem_Erase(InstanceId, TargetAddress, Length)</code>. <code>Mem</code> nimmt den Low-Level-Job an und quittiert synchron.</li>\n<li><code>MemAcc_MainFunction()</code> ruft die Treiber-Zustandsmaschine <code>Mem_MainFunction()</code> auf (bzw. diese läuft parallel via SchM), um den hardwareseitigen Löschvorgang (z. B. Flash Controller Status-Register-Abfrage) voranzutreiben.</li>\n<li><code>MemAcc</code> pollt das Ergebnis des Sektor-Jobs synchron über <code>Mem_GetJobResult(InstanceId)</code>. Sobald das Ergebnis <code>MEM_JOB_OK</code> signalisiert, inkrementiert <code>MemAcc</code> auf die nächste Sektoradresse, bis alle Sektoren der ursprünglichen Gesamtlänge gelöscht sind.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Asynchrone Benachrichtigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreichem Abschluss aller Sektoren triggert <code>MemAcc</code> aus dem Kontext der <code>MemAcc_MainFunction</code> den konfigurierten Callback <code>&lt;UpperLayer&gt;_JobEndNotification()</code>.</li>\n<li><code>Upper Layer</code> übernimmt die Weiterverarbeitung (z. B. Schreibfreigabe oder Statusübergabe an <code>NvM</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (Nicht-blockierend):</strong> <code>MemAcc_Erase()</code> ist strikt asynchron auszulegen. Es darf keine Busy-Wait-Schleifen auf Hardware-Ebene enthalten.</li>\n<li><strong>Sektor-Alignment & Granularität:</strong> <code>MemAcc</code> übernimmt das Mapping von logischen Bereichen auf physische Sektorgrenzen (<code>Sector Erase Sizes</code>). Anwendungsentwickler müssen sicherstellen, dass Längen- und Adressangaben den im BSW-Konfigurator hinterlegten Sektor-Restriktionen (<code>MemAccSectorBatch</code>, <code>MemAccAddressArea</code>) genügen.</li>\n<li><strong>Task-Scheduling (SchM):</strong></li>\n<li>Die Taktrate von <code>MemAcc_MainFunction()</code> und <code>Mem_MainFunction()</code> bestimmt maßgeblich die Latenz zwischen den Einzelsektor-Löschvorgängen.</li>\n<li>Werden beide Funktionen in derselben Task oder in unterschiedlichen BSW-Tasks ausgeführt, muss auf Reentrancy-Regeln und Mutex-Konfigurationen (<code>SchM_Enter_MemAcc</code>, <code>SchM_Exit_MemAcc</code>) geachtet werden.</li>\n<li><strong>Callback-Restriktionen (<code>JobEndNotification</code>):</strong> Der Callback wird im Kontext der <code>MemAcc_MainFunction()</code> ausgeführt (BSW-Task-Kontext). Dort dürfen keine langwierigen oder blockierenden Operationen ausgeführt werden, um Deadlocks oder Task-Jitter im BSW-Scheduler zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-a0c36af2b06e209b", "to": "FIG-3e845dd7133023bc", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
